/* GENERATED by gen_hcon_vault.py -- models are generated.
   SAT_FINTXN_PREMIUM
   anchor      : HUB_FINANCIAL_TRANSACTION   (kind: hub, origin: map.anchor)
   track       : ratified
   history     : SCD2
   feeders     : 1 emitted of 13 (one per source view AND run)
   runs        : 1 -- opus_health_legacy_v4
   payload     : 7 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_FINANCIAL_TRANSACTION_HK
   hashdiff    : SAT_FINTXN_PREMIUM_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   INTRA-RUN FAN-IN, 3 attribute/run pair(s) with more than one writer, of
   which 3 are genuinely ARBITRARY. WITHIN one run several source views
   write the same attribute and the map declares NO precedence among them,
   so max() picks arbitrarily -- BUT ONLY AMONG UNDISCRIMINATED WRITERS. A
   writer carrying a resolved `instance` or a declared `redundant_of` is
   SEPARATED, not competing: a nominee's name and a policyholder's name on
   one satellite are DIFFERENT ROWS. BOTH SCOPES are quoted below because a
   bare writer count overstates the arbitrariness -- on PARTY_FULL_NAME it
   overstates it nearly fivefold.
   DECLARED, NOT RESOLVED: choosing among same-run writers would invent an
   authority the map does not provide. NO CROSS-RUN DECISION REACHES THIS.
     COLLECTION_MODE                        opus_health_legacy_v4  9 writer(s), of which 9 UNDISCRIMINATED (0 separated by a resolved instance, 0 by redundant_of)  [CROSS-TABLE: check_collapse groups on (table, satellite, attribute, instance, child_key) and CANNOT see this]
     LOADING_AMOUNT                         opus_health_legacy_v4  2 writer(s), of which 2 UNDISCRIMINATED (0 separated by a resolved instance, 0 by redundant_of)  [CROSS-TABLE: check_collapse groups on (table, satellite, attribute, instance, child_key) and CANNOT see this]
     NET_PREMIUM                            opus_health_legacy_v4  3 writer(s), of which 3 UNDISCRIMINATED (0 separated by a resolved instance, 0 by redundant_of)  [CROSS-TABLE: check_collapse groups on (table, satellite, attribute, instance, child_key) and CANNOT see this]
   A load-time assertion in models/assertions/ counts the DISTINCT
   values the undiscriminated writers actually supply per key. Until it
   runs, whether they ever disagree is UNKNOWN, not zero.
*/

with feeders as (
    select
        md5(upper('HUB_FINANCIAL_TRANSACTION|' || (HUB_FINANCIAL_TRANSACTION_BK__PTRANSACTION_ID))) as HUB_FINANCIAL_TRANSACTION_HK
        , cast(null as varchar) as INSTALMENT_AMOUNT
        , cast(null as varchar) as NET_PREMIUM
        , cast(null as varchar) as GROSS_PREMIUM
        , cast(null as varchar) as BASE_PREMIUM
        , PAYMENT_MODE as COLLECTION_MODE
        , cast(null as varchar) as DISCOUNT_AMOUNT
        , cast(null as varchar) as LOADING_AMOUNT
        , 'BJAZ_HEALTH_WEBSERVICE_INFO' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_health_webservice_info') }}
    where (nullif(trim(PTRANSACTION_ID),'')) is not null
),

resolved as (
    select
        HUB_FINANCIAL_TRANSACTION_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then INSTALMENT_AMOUNT end) as INSTALMENT_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then NET_PREMIUM end) as NET_PREMIUM,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then GROSS_PREMIUM end) as GROSS_PREMIUM,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BASE_PREMIUM end) as BASE_PREMIUM,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then COLLECTION_MODE end) as COLLECTION_MODE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DISCOUNT_AMOUNT end) as DISCOUNT_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then LOADING_AMOUNT end) as LOADING_AMOUNT,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_FINANCIAL_TRANSACTION_HK
),

hashed as (
    select
        *,
        case when INSTALMENT_AMOUNT is not null or NET_PREMIUM is not null or GROSS_PREMIUM is not null or BASE_PREMIUM is not null or COLLECTION_MODE is not null or DISCOUNT_AMOUNT is not null or LOADING_AMOUNT is not null
                     then md5(upper(coalesce(cast(INSTALMENT_AMOUNT as varchar), '') || '|' || coalesce(cast(NET_PREMIUM as varchar), '') || '|' || coalesce(cast(GROSS_PREMIUM as varchar), '') || '|' || coalesce(cast(BASE_PREMIUM as varchar), '') || '|' || coalesce(cast(COLLECTION_MODE as varchar), '') || '|' || coalesce(cast(DISCOUNT_AMOUNT as varchar), '') || '|' || coalesce(cast(LOADING_AMOUNT as varchar), '')))
                end as SAT_FINTXN_PREMIUM_HASHDIFF
    from resolved
)

select * from hashed
where HUB_FINANCIAL_TRANSACTION_HK is not null
  and SAT_FINTXN_PREMIUM_HASHDIFF is not null
